import {uid} from './model.js';
import {newScene} from './authoring-model.js';
export const EVENT_PRESETS={dialogue:'NPC dialogue',item:'One-time item',heal:'Healer',shop:'Shop',trainer:'Trainer battle',gift:'Pokémon gift',tremor:'Tremor',rain:'Start rain',fetch:'Collect supplies',exchange:'Item exchange',delivery:'Deliver a parcel',bounty:'Trainer bounty',rescue:'Lost Pokémon',treasure:'Hidden treasure',toll:'Paid passage',inn:'Rest at an inn',donation:'Donation box',badgeReward:'Badge reward',milestone:'Story milestone reward',survey:'Exploration reward',puzzle:'Puzzle reward',escort:'Escort arrival',rumour:'Branching quest hint'};
export const PRESET_HINTS={fetch:'Choose the requested item, quantity and reward.',exchange:'Repeatable trade. The reward is checked before anything is taken.',delivery:'Choose the parcel item and change the payment.',bounty:'Choose a native trainer team and the reward.',rescue:'A cry, portrait and one-time reward. Choose the Pokémon.',treasure:'One-time find with dialogue after collection.',toll:'Choose a gate on this map and the fee.',inn:'Repeatable paid party healing.',donation:'Repeatable donation with a confirmation.',badgeReward:'Choose the badge and reward. Native badge support depends on the ROM.',milestone:'Choose an existing saved milestone before export.',survey:'Choose a location to visit before claiming the reward.',puzzle:'Choose a saved counter and the required solved value.',escort:'Place at the destination and choose the escort-start milestone.',rumour:'A repeatable optional hint with Yes / No branches.'};
export function eventPreset(project,kind,x,y){
 if(!Object.hasOwn(EVENT_PRESETS,kind))throw Error('Unknown event preset.');const n=newScene(project,x,y);n.title=EVENT_PRESETS[kind];
 const say=text=>({type:'say',text}),abort={type:'abort'},give=(id=13,quantity=1)=>({type:'item',operation:'give',itemId:id,quantity}),take=(id=13,quantity=1)=>({type:'item',operation:'take',itemId:id,quantity}),money=(amount,operation='give')=>({type:'money',operation,amount}),confirm=(text,yes)=>({type:'choice',text,yes,no:[say('Another time, then.'),abort]});
 const flag=project.questFlags?.find(q=>!q.hidden)?.id||'',variable=project.authoring?.variables?.[0]?.id||'';
 const recipes={dialogue:[say('Hello!')],item:[give(),say('Take this with you.')],heal:[say('Let me help you.'),{type:'heal'},say('All better.')],shop:[say('What do you need?'),{type:'shop',items:[13,4]}],trainer:[{type:'battle',trainerId:1,intro:'Ready for a battle?',defeat:'Well fought!'}],gift:[{type:'giveMon',species:1,level:5,itemId:0}],tremor:[{type:'shake',x:2,y:2,count:8,interval:4}],rain:[{type:'weather',weather:3}],fetch:[confirm('Can you spare three of these supplies?',[give(4,2),take(13,3),say('That is everything. Thank you!')])],exchange:[confirm('Trade one of these for one of mine?',[give(4),take(),say('A fair trade!')])],delivery:[confirm('Is that the parcel for me?',[money(500),take(),say('It arrived safely. Here is your payment.')])],bounty:[confirm('Will you take on this trainer?',[{type:'battle',trainerId:1,intro:'Show me what you can do!',defeat:'You earned that reward.'},give(4,3),say('Good work. Here is your reward.')])],rescue:[{type:'cry',species:25,wait:true},{type:'portrait',species:25},say('You found the lost Pokémon!'),give(4,2),say('Thanks for bringing us back together.')],treasure:[{type:'sound',soundId:5},say('Something is tucked away here.'),give(4),say('You found it!')],toll:[confirm('Pay 100 to open the way?',[{type:'gate',gateId:''},money(100,'take'),say('The way is open.')])],inn:[confirm('Rest here for 100?',[money(100,'take'),{type:'fade',mode:0},{type:'heal'},{type:'fade',mode:1},say('You look well rested.')])],donation:[confirm('Donate 100 to the town fund?',[money(100,'take'),say('Thank you for helping the town.')])],badgeReward:[give(4,3),say('A reward for your progress.')],milestone:[give(4),say('You kept your promise. This is for you.')],survey:[give(4),say('So you made it there! Here is your reward.')],puzzle:[give(4),say('You solved it!')],escort:[give(4),say('We made it. Thank you for your help.')],rumour:[{type:'choice',text:'Want a clue?',yes:[say('Look where the path meets the shore.')],no:[say('Enjoy the search.')]}]};
 n.runtime.steps=recipes[kind];
 if(['item','gift','trainer','fetch','delivery','bounty','rescue','treasure','badgeReward','milestone','survey','puzzle','escort'].includes(kind)){n.runtime.repeat='once';n.runtime.repeatSteps=[say('Thanks again.')];}
 if(['fetch','exchange'].includes(kind)){n.runtime.conditions=[{kind:'item',itemId:13,quantity:kind==='fetch'?3:1}];n.runtime.failText='Bring the requested supplies, then speak to me again.';}
 if(kind==='delivery'){n.runtime.conditions=[{kind:'item',itemId:13,quantity:1}];n.runtime.failText='I am waiting for a parcel.';}
 if(['toll','inn','donation'].includes(kind)){n.runtime.conditions=[{kind:'money',amount:100}];n.runtime.failText='You need 100 for this.';}
 if(kind==='badgeReward'){n.runtime.conditions=[{kind:'badge',badge:1}];n.runtime.failText='Come back when you have earned the badge.';}
 if(['milestone','escort'].includes(kind)){n.runtime.conditions=[{kind:'flag',flagId:flag,value:true}];n.runtime.failText='There is something to finish first.';}
 if(kind==='survey'){n.runtime.conditions=[{kind:'visited',mapId:'' ,value:true}];n.runtime.failText='Visit that location, then return to me.';}
 if(kind==='puzzle'){n.runtime.conditions=[{kind:'variable',variableId:variable,operator:'ge',value:3}];n.runtime.failText='The puzzle is not solved yet.';}
 if(kind==='treasure')n.runtime.repeatSteps=[say('There is nothing else here.')];
 const ids=steps=>steps.map(s=>{const a={id:uid(),...s};for(const key of ['yes','no','then','else'])if(a[key])a[key]=ids(a[key]);return a;});n.runtime.steps=ids(n.runtime.steps);n.runtime.repeatSteps=ids(n.runtime.repeatSteps);return n;
}
